template <typename T>
__device__ static __forceinline__ T RowSumCombine0(T p0, T p1) {
  return (p0 + p1);
}

// RowSum: launch 512 CTAs x 1024 threads (derived from the loop annotations: gridDim = max over LNTs of CTA LoC products, blockDim = (max warp-K product) x 32 — the runtime validates)
// dynamic SMEM pool: 128 B (v0: disjoint offsets, zero reuse)
namespace {

__global__ void __launch_bounds__(1024) RowSum(uint32_t R, uint32_t e4, uint32_t C, const float* __restrict__ x, const float* __restrict__ z, float* __restrict__ out) {
