  {
    // CTA-space mapping (absolute LoC per dim: 512u — the factorization this nest remaps)
    tca::rt::GridMapping grid_map0(kinfo, 1u, 512u);
    // per-CTA thread-space mapping (absolute warp counts K per dim: 32u)
    tca::rt::ThreadMapping thread_map1(kinfo, 1u, 32u);
    auto c0 = 0.0f;
    auto c1 = 0u;
    auto v0 = R;
    auto c2 = 2u;
    auto v1 = C;
    auto c3 = 1u;
    auto v2 = 4u;
    auto v3 = grid_map0.index(0u);
    auto v4 = (v3 * c2);
    auto v5 = thread_map1.index(0u);
    auto v6 = (v5 * c2);
    auto v7 = thread_map1.lane_id();
    auto v8 = (v7 + c3);
    auto v9 = (v8 * c3);
    // warp reduction — the combiner is runtime-owned; per-element brackets [Init → reduced-dim walks (Reduce(value)) → Combine]
    tca::rt::WarpReducer<float> reducer0(c0, RowSumCombine0, thread_map1, tca::rt::SmemView<float, 1u>(reinterpret_cast<float*>(tca_smem + 0u), 32u));
    // @R tile-between rounds — sequential, T=2, LoC=1
    for (auto R_it0 = tca::rt::SeqIterator(0u, 2u, v0); R_it0.Has(); R_it0.Next()) {
      auto v10 = tca::rt::umin(R_it0.Index(), v0);
      auto v11 = (v0 - v10);
      auto v12 = tca::rt::umin(c2, v11);
      // @C tile-between rounds — CTA, T=2, LoC=512 (map dim 0)
      for (auto C_it1 = tca::rt::CtaIterator(grid_map0, 0u, 512u, 0u, 1024u, v1); C_it1.Has(); C_it1.Next()) {
