        auto v14 = tca::rt::umin(v13, v1);
        auto v15 = (v1 - v14);
        auto v16 = tca::rt::umin(c2, v15);
        // @R walk — sequential, LoC=1
        for (auto R_it2 = tca::rt::SeqIterator(0u, 1u, v12); R_it2.Has(); R_it2.Next()) {
