void RowSumLaunch(uint32_t e4, const tca::Tensor<float, 3u>& x, const tca::Tensor<float, 3u>& z, tca::Tensor<float, 2u>& out, cudaStream_t tca_stream) {
  const uint32_t R = x.Dim(0u);
  const uint32_t C = x.Dim(2u);
  TCA_REQUIRE(z.Dim(0u) == R, "z.Dim(0) must equal R (dim R)");
  TCA_REQUIRE(z.Dim(2u) == C, "z.Dim(2) must equal C (dim C)");
  TCA_REQUIRE(out.Dim(0u) == R, "out.Dim(0) must equal R (dim R)");
  TCA_REQUIRE(out.Dim(1u) == C, "out.Dim(1) must equal C (dim C)");
  tca::rt::ValidateLaunch(dim3(512u, 1u, 1u), dim3(1024u, 1u, 1u), 128u, 512u);
  RowSum<<<dim3(512u, 1u, 1u), dim3(1024u, 1u, 1u), 128u, tca_stream>>>(R, e4, C, x.Data(), z.Data(), out.Data());
  TCA_CUDA_CHECK(cudaGetLastError());
}
